about_disclaimer_title: "Aviso legal",
about_disclaimer_purpose: "ps5upload se ofrece únicamente con fines de investigación, educación, interoperabilidad y desarrollo de homebrew. No está afiliado, avalado ni relacionado con Sony Interactive Entertainment Inc. «PlayStation» y «PS5» son marcas comerciales de Sony Interactive Entertainment Inc., utilizadas aquí solo con fines identificativos.",
about_disclaimer_piracy: "Úsalo solo con hardware de tu propiedad y con contenido que poseas legalmente. No debe utilizarse para copiar, distribuir ni ejecutar software que no tengas derecho a usar.",
about_disclaimer_risk: "Este software se proporciona «tal cual», sin garantía de ningún tipo. Utilizar una consola modificada puede dañarla de forma permanente, destruir irreversiblemente partidas guardadas y licencias, y provocar el baneo de tu cuenta o tu consola. Lo usas totalmente bajo tu propia responsabilidad y aceptas las consecuencias. Haz copia de seguridad de todo lo que no puedas permitirte perder antes de empezar.",
