imgbrowse_explain: "Explora cualquier imagen de juego o paquete que ps5upload lee (.exfat, .ffpkg, .ffpfs, .ffpfsc, o un .pkg creado con la clave de depuración) en cualquier ordenador, sin montarla. Guarda un archivo o una carpeta en el ordenador, o cambia archivos y escribe una copia editada: la imagen que abriste nunca se modifica.",
