"pkg.reason.stream_unreachable": "La PS5 nunca llegó a este equipo para descargar el paquete. Permite ps5upload en el firewall de este equipo (en Windows, para redes privadas y públicas), mantén el equipo y la PS5 en la misma red sin VPN y configura el servidor proxy de la PS5 en «No usar». Subir e instalar funciona sin esta conexión.",
