"fpkg.about": "Indica una carpeta de juego, o una imagen de montaje .exfat o .ffpkg. El conversor lee el árbol, comprueba que está todo lo que necesita un paquete ejecutable y escribe un .pkg en formato debug en la carpeta de salida.",
"fpkg.aboutWhere": "La conversión se ejecuta en la máquina que aloja el motor —este equipo, un host Docker o un dispositivo Android—, no en la consola. Nada llega a la consola hasta que instalas el paquete: por streaming desde este equipo, o subiéndolo antes a la PS5.",
"fpkg.aboutSource": "El origen debe ser un árbol de juego ya descifrado. Una instalación retail no se puede desempaquetar aquí, y la comprobación de abajo lo indicará si es lo que elegiste.",
"fpkg.aboutChecks": "Qué busca la comprobación",
"fpkg.checkEboot": "Un eboot.bin en la raíz del árbol: el módulo del título. Debe ser un ELF sin procesar o un SELF envuelto; un módulo firmado para retail no se puede reempaquetar.",
"fpkg.checkParam": "sce_sys/param.json, y ningún sce_sys/param.sfo: un param.sfo envía la ruta de inicio de la consola por la vía de PS4.",
"fpkg.checkIcons": "Un ID de contenido de 36 caracteres, ambos iconos y el módulo de derechos sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Que el valor DRM del paquete sea estándar. Un valor gratuito o actualizable hace que la consola bloquee el título; solo se reescribe en el paquete y tu propio archivo nunca se modifica.",
"payloads_essentials_title": "Recomendados junto a ps5upload",
"payloads_essentials_body": "Si configuras una consola por primera vez, estos tres cubren casi todo lo que ps5upload espera encontrar: kstuff-lite (parches del kernel de los que depende la mayoría del homebrew), ShadowMount+ (montar imágenes de juegos desde el almacenamiento) y nanoDNS (mantener la consola fuera de las actualizaciones de Sony). Todo lo demás de esta lista es opcional.",
