volumes_pkg_copies_hint: "Qué hace esta opción: «Subir e instalar» primero copia el archivo .pkg a la PS5 y luego instala desde esa copia. Esto solo decide en qué unidad se guardan esas copias. No cambia dónde se instalan los juegos (lo decide la PS5 en sus ajustes de almacenamiento), y «Transmitir e instalar» no guarda ninguna copia. Si la unidad elegida no está conectada, las copias van al almacenamiento interno.",
