"share.note.package": "El paquete se transmite a la PS5 y se instala. No se copia nada a la PS5 antes.",
"share.note.archive": "El archivo se abre en Instalar paquetes desde un archivo, donde se listan los paquetes que contiene. Instálalos desde allí.",
