"share.unsupported": "PS5Upload instala paquetes .pkg y .fpkg y archivos ZIP, 7z o RAR. Esto no es ninguno de ellos.",
"share.too_large": "Este archivo pesa más de {limit}, demasiado para copiarlo en la app. Descárgalo primero en el teléfono (por ejemplo en Descargas) y vuelve a compartirlo desde la app Archivos.",
"share.no_space": "No hay espacio libre suficiente en el teléfono para copiarlo en la app.",
"share.copy_failed": "No se pudo leer el archivo desde la app que lo compartió. Descárgalo primero en el teléfono y vuelve a compartirlo desde la app Archivos.",
"share.remote_engine": "Esta app usa un motor en otro ordenador, que no puede abrir archivos de este.",
"share.not_connected": "Conéctate primero a una PS5. Esto espera aquí hasta que lo envíes o lo canceles.",
"install.description.v2": "Instala paquetes .pkg y .fpkg en tu PS5: directamente desde este ordenador o un enlace (Transmitir e instalar), o desde una copia puesta antes en la PS5 (Subir e instalar).",
