health_junk_explain_v2: "Cosas que ps5upload creó y ya no necesita: archivos sin terminar de transferencias interrumpidas, copias de paquetes que llevan más de una hora en su carpeta temporal y archivos antiguos de pruebas de velocidad. Solo se miran las carpetas propias de ps5upload; tus juegos, paquetes y partidas guardadas no se tocan nunca.",
