stop: "Detener",
activity_description_v2: "Todo lo que la app hace y ha hecho en tus consolas: subidas, descargas, instalaciones y operaciones con archivos. Desde aquí puedes detener o reintentar una. Se conservan las últimas 100, también tras reiniciar.",
fw_spoof_subtitle_v2: "Comprueba si la versión de firmware que informa esta PS5 ha sido cambiada por un payload de suplantación, para que conozcas su versión real antes de instalar algo que dependa de ella.",
health_subtitle_v2: "Comprueba que la PS5, esta app y la red entre ambas funcionan, dice qué arreglar cuando algo no va y mide lo rápido que se mueven los archivos entre ellas.",
remotePlay_subtitle_v2: "Configura esta PS5 para Remote Play y obtén el PIN que empareja la app PS Remote Play con ella.",
saves_description_v2: "Datos guardados en la PS5, una entrada por juego. Haz una copia de las partidas de un juego en un .zip en este ordenador y restáuralas más tarde.",
shell_description_v2: "Escribe comandos que se ejecutan en la PS5, en el proceso del ayudante. Para uso avanzado. La salida está limitada a 256 KB por comando; las flechas arriba y abajo recuperan comandos anteriores.",
"arcpkg.links.go": "Descargar {count} archivo(s)",
"arcpkg.links.help": "Pega el enlace directo al archivo comprimido, o a cada parte de uno dividido, uno por línea. Los archivos se descargan a este ordenador (Downloads/ps5upload), que necesita espacio para todos; después los paquetes que contienen se descomprimen en la PS5 como arriba.",
"arcpkg.links.kept": "Hay {count} archivo(s) descargado(s) en {dir}. Se conservan para poder reintentar la instalación; bórralos cuando termines.",
"arcpkg.links.progress": "Descargando el archivo {n} de {count} a este ordenador…",
"arcpkg.links.title": "El archivo comprimido está tras enlaces de descarga",
"arcpkg.noFirstPart": "Los archivos se descargaron, pero ninguno es la primera parte de un archivo comprimido (.zip, .7z, .rar o .part1.rar). Revisa los enlaces.",
"fpkg.image.done": "Imagen de juego escrita y leída de vuelta. Cópiala a una unidad de la PS5 (Subir) y ShadowMount+ la montará.",
"fpkg.image.what": "Un archivo que copias a una unidad de la PS5, que ShadowMount+ monta y muestra en la pantalla de inicio. No se instala nada.",
"fpkg.image.folderOnly": "Solo una carpeta de juego de este equipo puede convertirse en imagen de juego.",
"fpkg.image.folderOnly_v2": "Solo una carpeta de juego (en este equipo, un servidor guardado o la PS5) puede convertirse en imagen de juego.",
"fpkg.image.folderOnly_v4": "Solo una carpeta de juego, una imagen de juego o un archivo comprimido (.zip, .7z, .rar) que contenga un juego puede convertirse en una imagen de juego; el archivo comprimido se descomprime primero en la carpeta de salida.",
"fpkg.card.make": "② Qué crear",
"fpkg.card.options_v2": "③ Opciones",
"fpkg.card.run_v2": "④ Crear e instalar",
"fpkg.options.image": "Imagen",
"fpkg.make.pkg_title": "Un paquete (.pkg)",
"fpkg.make.pkg_body": "Se instala en la PS5 como un juego de la tienda, transmitido desde aquí o subido antes. Los juegos de PS4 funcionan en cualquier firmware; los de PS5 en 11.60 o inferior.",
"fpkg.make.image_title": "Una imagen de juego",
"fpkg.make.image_body": "Un archivo en una unidad de la PS5 que ShadowMount+ monta y muestra en la pantalla de inicio. No se instala nada y funciona en firmwares donde un paquete de PS5 no.",
"fpkg.make.recommended": "Recomendado",
"fpkg.make.recommended_fw": "Recomendado en FW {fw}",
"fpkg.make.pick_game": "Comprueba un juego en ① y se marcará la mejor opción para tu PS5.",
"fpkg.make.why_image": "Este juego de PS5 se instalaría como paquete pero no funcionaría en FW {fw}; como imagen sí.",
"fpkg.make.why_pkg": "Un paquete es la opción habitual: se instala y funciona como cualquier otro juego.",
