connection_payload_engine_unreachable: "La app no pudo conectar con su propio motor en este ordenador, así que no puede saber si el ayudante se inició en la PS5. No es un problema de la PS5: el aviso de arriba de la ventana dice por qué y puede reiniciar el motor. Después pulsa Enviar ayudante otra vez. ({error})",
"engine_problem.missing.fix": "Restaura ps5upload-engine desde la cuarentena de tu antivirus (o permítelo), o reinstala la app.",
"engine_problem.missing.why": "Falta el programa del motor en la carpeta de la app. El software de seguridad a veces lo pone en cuarentena.",
"engine_problem.port.fix": "Pulsa Reiniciar motor. Si no funciona, permite ps5upload-engine en tu cortafuegos o antivirus y reinicia la app.",
"engine_problem.port.why": "Algo ocupa la dirección del motor ({url}) pero no responde: otro programa en ese puerto, o software de seguridad que bloquea las conexiones a él.",
"engine_problem.proxy.fix": "Desactiva el proxy o la herramienta VPN para direcciones locales (127.0.0.1), o inicia la app sin la variable http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Las peticiones al motor fueron a un proxy configurado en este ordenador en lugar de al motor.",
