"profile.np.body": "Hace que la PS5 trate la cuenta conectada como si hubiera iniciado sesión en PlayStation Network, sin contactar con Sony. Algunas funciones de la consola solo se abren para una cuenta con sesión iniciada, entre ellas Remote Play. Usa np-fake-signin de earthonion, que se descarga de la página del proyecto al pulsar el botón.",
