"fakegame.fw.body": "Se instalará, pero los paquetes de juegos falsos de PS5 no se pueden jugar en firmware superior a {last}. Los paquetes de PS4 funcionan bien y las apps homebrew de PS5 se inician con normalidad.",
"fakegame.fw.launch": "Los paquetes de juegos falsos de PS5 no se pueden jugar en firmware superior a {last} (esta consola tiene {fw}). Si este juego se instaló desde un paquete falso, por eso no arranca. Los paquetes de PS4 funcionan bien.",
"fakegame.fw.more": "¿Por qué?",
