"install_help_wont_launch": "¿El juego no se inicia?",
install_hint_setup_exe: "Se abrió el instalador: síguelo y actualizará PS5Upload en su sitio.",
install_path_fallback_hint: "Un último recurso para un paquete que ya está en la PS5, cuando la PS5 lo rechaza desde su propio almacenamiento y tampoco puede obtenerlo desde este ordenador. Solo se usa para un juego base que no está instalado, así que no puede eliminar nada. Sin probar: ha funcionado en el firmware 11.20 y se rechaza en 13.60. Si lo pruebas, por favor, informa de si funcionó.",
install_path_fallback_label: "Instalar por ruta de archivo cuando la PS5 no puede llegar a este ordenador",
"installed_fix_permissions": "Corregir permisos: hacer que la carpeta de este juego sea legible y ejecutable por la PS5 (chmod 777)",
