"minion_lan_hint": "Desactivado: solo el navegador de la propia PS5 lo abre. Activado: un teléfono, tableta u ordenador de la misma red también puede abrirlo, así que cualquiera en esa red puede. Actívalo solo en casa.",
"minion_open_here": "Abrir aquí",
"minion_remove_note": "Quitar desactiva Minion y borra lo que guarda en la PS5: sus favoritos de Archivos y carpetas recientes, su caché de la Biblioteca de juegos y su registro del mando. Las carpetas de red, los trucos y las copias de seguridad se conservan; la app del PC también los usa.",
"minion_remove": "Quitar Minion de esta PS5…",
"minion_remove_title": "¿Quitar PS5Upload Minion?",
"minion_remove_confirm": "Su icono de la pantalla de inicio y su página desaparecen, y se borran sus propios archivos en la PS5. El ayudante lo mantiene desactivado a partir de ahora. Puedes volver a activarlo aquí en cualquier momento.",
"minion_remove_go": "Quitar",
"minion_removed_done": "Minion se ha quitado: su icono y su página ya no están y se borraron {n} de sus archivos en la PS5. Sigue desactivado, incluso tras reiniciar el ayudante, hasta que lo actives aquí.",
"fs_dragout_n_items": "{n} elementos",
"fs_dragout_over_cap": "Un arrastre trae hasta 4 GB. Para más, clic derecho → Descargar.",
"fs_drag_hint_move": "Arrastra archivos y carpetas fuera de la ventana para copiarlos a este ordenador, o arrástralos dentro para copiarlos aquí. Mantén pulsada Alt (⌥ Option en un Mac) mientras arrastras para moverlos a una carpeta de aquí.",
"fs_drag_hint": "Arrastra archivos y carpetas fuera de la ventana para copiarlos a este ordenador, o arrástralos dentro para copiarlos aquí.",
"fs_browser_drop_folder": "No se pueden soltar carpetas en un navegador",
"fs_browser_drop_folder_body": "Suelta los archivos que contiene o usa la app de escritorio para copiar carpetas enteras.",
"collection.send_free_space": "Liberar espacio",
"game_show_in_files": "Mostrar en Archivos",
"game_search_files": "Buscar en los archivos de este juego",
"installed_uninstall_no_copy": "Tu Colección en este ordenador no tiene copia de este juego: guarda su paquete en algún sitio antes de desinstalarlo.",
"connection_send_payload_moved": "¿Quieres enviar otro payload (kstuff, etaHEN, cualquier .elf)? Está en Payloads → Enviar payload. Esta pantalla solo envía el ayudante de PS5Upload.",
"connection_send_payload_open": "Abrir Enviar payload",
"upload_elf_title": "Esto es un payload (.elf), no un juego",
"upload_elf_body": "Subirlo solo copia el archivo. ShadowMount+ recoge carpetas de juego (con eboot.bin y sce_sys) e imágenes de juego, nunca un .elf, así que no aparecerá en la pantalla de inicio. Para ejecutarlo, envíalo al cargador de la consola. Lo que hay que subir es una app homebrew que venga como imagen .ffpkg o .exfat, o como carpeta con eboot.bin.",
"netdoctor.hint.below_test": "Esta subida va a {speed}, muy por debajo de los {expected} que midió la prueba de velocidad.",
"netdoctor.hint.runs_at": "Esta subida va a {speed}.",
"netdoctor.hint.cause_source": "Lo que la frena es leer los archivos en este equipo, no la red: una unidad USB o un disco duro, una carpeta de red (NAS) o descomprimir un archivo son más lentos que la conexión. Copiar antes el juego a un SSD interno, o subir los archivos de un comprimido ya descomprimidos, da la velocidad completa.",
"netdoctor.hint.cause_disk": "Lo que la frena es la unidad de la PS5, no la red: una unidad USB externa, una unidad casi llena o miles de archivos pequeños (cada uno cuesta su propio tiempo) escriben más despacio de lo que entrega la conexión. Una imagen de juego (.ffpkg o .exfat) va como un solo archivo.",
"netdoctor.hint.cause_workers": "La PS5 sigue escribiendo lo que recibió, no está esperando a la red. Con muchos archivos pequeños cada uno cuesta su propio tiempo; una imagen de juego (.ffpkg o .exfat) va como un solo archivo.",
"netdoctor.hint.cause_cap": "Lo que la frena es el límite de velocidad de subida (unos {cap} MiB/s, en esta pantalla y en Ajustes). Ponlo en 0 para quitarlo.",
"profile.np.confirm_body_v2": "np-fake-signin escribe en la PS5 los archivos y ajustes de inicio de sesión de PlayStation Network para {user}. No se envía nada a Sony. Reinicia la PS5 después.",
"profile.np.side_effect": "Efecto secundario conocido: después, algunas consolas piden «Desactivar temporalmente las restricciones de la consola PS5» antes de abrir cualquier juego, y Ajustes > Usuarios y cuentas > Otros > Cerrar sesión puede quedar atenuado. La app guarda antes en la PS5 una copia de todo lo que cambia np-fake-signin, así que Deshacer el inicio de sesión aquí lo restaura.",
"profile.np.backing_up": "Guardando en la PS5 una copia de los ajustes actuales de la cuenta…",
"profile.np.backup_failed": "La PS5 no pudo guardar una copia de los ajustes de la cuenta, así que no se ejecutó np-fake-signin. Sustituye el ayudante por la versión de esta app e inténtalo de nuevo. ({error})",
"profile.np.step_restart_v2": "Reinicia la PS5. Para deshacerlo más tarde, pulsa Deshacer el inicio de sesión aquí y vuelve a reiniciar.",
"profile.np.undo": "Deshacer el inicio de sesión",
"profile.np.undo_hint": "En la PS5 se guarda una copia de los ajustes de esta cuenta de antes del inicio de sesión; esto la restaura.",
"profile.np.undo_confirm_title": "¿Deshacer el inicio de sesión?",
"profile.np.undo_confirm_body": "Devuelve los ajustes y archivos de {user} a como estaban antes de ejecutar np-fake-signin. Reinicia la PS5 después. Las funciones que necesitan una cuenta con sesión iniciada, como Remote Play, pueden dejar de abrirse hasta que vuelvas a iniciar sesión.",
"profile.np.undoing": "Restaurando los ajustes…",
"profile.np.undone": "Restaurado ({count} ajustes y archivos). Reinicia la PS5 para terminar.",
"profile.np.no_backup": "Esta cuenta tiene los ajustes de la plantilla de np-fake-signin (fecha de nacimiento 1983-04-12, el indicador de adulto sin conexión desactivado) y en esta PS5 no hay ninguna copia de antes, así que la app no puede deshacerlo. Si la PS5 ahora pide desactivar temporalmente las restricciones de la consola antes de abrir juegos: Ajustes > Familia y controles parentales > Restricciones de la consola PS5 (código 0000 salvo que lo hayas cambiado), y quita las restricciones allí.",
"linkdl.lz4_title": "Este enlace está comprimido con LZ4",
"linkdl.image_title": "Este enlace es una imagen de juego",
"linkdl.lz4_help": "ps5upload puede descomprimirlo mientras se descarga, así la PS5 recibe el archivo descomprimido. No se guarda nada en este ordenador y la PS5 solo necesita espacio para el archivo descomprimido.",
"linkdl.lz4_unpack": "Descomprimir por el camino",
"linkdl.lz4_unpack_hint": "Desactivado: el archivo .lz4 se guarda en la PS5 tal cual.",
"linkdl.image_hint": "Una imagen de juego {kind}. ShadowMount+ la monta tal cual desde una carpeta que examina, como homebrew en una unidad. El archivo aparece ahí solo cuando está completo.",
