"rp_controls_hint": "También funciona un mando: conéctalo o emparéjalo con este dispositivo. Shift + arrastrar en la imagen es un dedo en el panel táctil.",
"rp_hid_touchpad": "Usar el panel táctil del DualSense",
"rp_hid_touchpad_hint": "El navegador pregunta qué mando usar: elige el DualSense.",
"rp_hid_touchpad_on": "El panel táctil del DualSense se lee en este navegador.",
"rp_settings": "Ajustes",
"rp_running_elsewhere": "Jugar se está usando en {name}",
"rp_show_here": "Mostrar aquí",
"rp_running_elsewhere_body": "Se inició desde otra ventana o antes de recargar esta página, y sigue en marcha.",
"rpg_user_title": "Inicia sesión con un usuario en la PS5",
"rpg_user_body": "En la consola, elige el usuario con el que vas a jugar. No hace falta que nadie se quede delante de la pantalla, pero el usuario debe tener la sesión iniciada. Usa un usuario sin código de acceso: un código impide el inicio de sesión automático cuando la consola se enciende.",
"rpg_account_title": "Dale un ID de cuenta a ese usuario",
"rpg_account_body": "Remote Play se vincula con un ID de cuenta. Un usuario vinculado a PlayStation Network ya tiene uno; un usuario sin conexión necesita que se le asigne uno en Usuarios, arriba (sirve cualquier ID; anótalo, las partidas que guardes después quedan ligadas a él).",
"rpg_signin_title": "Inicia sesión con la cuenta en PlayStation Network (sin conexión)",
"rpg_signin_body": "La PS5 solo deja usar Remote Play a una cuenta con sesión iniciada. Si el ajuste de Remote Play de la propia consola aparece atenuado, ejecuta el inicio de sesión sin conexión de abajo (no se envía nada a Sony) y luego reinicia la PS5. Se puede deshacer.",
"rpg_signin_fix": "Ir al inicio de sesión",
"rpg_service_title": "Activa Remote Play",
"rpg_service_body": "Ajustes › Sistema › Remote Play › Habilitar Remote Play. La app puede activarlo por ti y, en firmware 10.00 y posterior, permitirlo también para este usuario.",
"rpg_rest_title": "Permite encender la PS5 desde el modo de reposo",
"rpg_rest_body": "Ajustes › Sistema › Ahorro de energía › Funciones disponibles en modo de reposo: activa «Permanecer conectado a Internet» y «Habilitar encender la PS5 desde la red». Sin ellas, una consola en modo de reposo no se puede encender y su red se duerme a los pocos segundos. Solo la consola puede mostrar estos ajustes.",
"rpg_pair_title": "Empareja esta app con la consola",
"rpg_pair_body": "Conexión › Encender e iniciar sesión › Configurar. Un clic registra esta app en la PS5 (como al emparejar la app PS Remote Play) y guarda sus claves en este ordenador. La transmisión, el encendido y el inicio de sesión las usan; vuelve a hacerlo tras restablecer la consola o cambiar de usuario.",
"rpg_play_title": "Jugar",
"rpg_play_body": "Abre Remote Play y pulsa Iniciar: la app enciende la consola si está en reposo, inicia sesión y transmite. Juega con un mando conectado a este ordenador, con el teclado o con la pantalla táctil. Para usar en su lugar la app PS Remote Play de Sony o chiaki-ng, solicita un PIN abajo e introdúcelo allí.",
"rpg_play_fix": "Abrir Remote Play",
"rpg_title": "Configurar Remote Play",
"rpg_progress": "{done} de {n} pasos comprobados hechos",
"rpg_on_console": "compruébalo en la consola",
"rpg_trouble": "Si sigue sin funcionar",
"rpg_t_start_q": "Iniciar aparece en gris en la pantalla Jugar.",
"rpg_t_start_a": "Esta app aún no está emparejada con esa consola: haz el paso 6 (Conexión › Encender e iniciar sesión › Configurar).",
"rpg_t_pair_q": "Al configurar el emparejamiento dice que no hay ningún usuario con sesión iniciada y una cuenta activada.",
"rpg_t_pair_a": "Pasos 1 y 2: inicia sesión con un usuario en la PS5 y dale un ID de cuenta; luego inténtalo de nuevo.",
"rpg_t_grey_q": "El ajuste de Remote Play de la propia PS5 aparece atenuado.",
"rpg_t_grey_a": "La cuenta no tiene la sesión iniciada en PlayStation Network. Ejecuta el inicio de sesión sin conexión (paso 3) y reinicia la PS5.",
"rpg_t_wake_q": "La consola no se enciende, o se enciende pero se queda en la pantalla de selección de usuario.",
"rpg_t_wake_a": "Revisa el paso 5 en la consola. Un usuario con código de acceso impide el inicio de sesión automático. Si la consola se restableció o cambió el usuario, vuelve a configurar el emparejamiento (paso 6).",
"rpg_t_black_q": "La imagen se queda en negro, se entrecorta o el sonido chasquea.",
"rpg_t_black_a": "Usa una conexión por cable o Wi-Fi de 5 GHz para la PS5 y este ordenador, y prueba 720p o 30 fps en los ajustes de Remote Play. El cortafuegos de este ordenador debe permitir la app en la red local (Remote Play usa los puertos TCP y UDP 9295–9304). En un navegador, usa un Chrome, Edge o Safari actual: la imagen necesita WebCodecs.",
"rpg_t_busy_q": "Dice que la PS5 aún está cerrando la última sesión, o que otra consola está transmitiendo.",
"rpg_t_busy_a": "Solo transmite una consola a la vez, y la PS5 necesita hasta 30 segundos después de que termine una sesión. Detén la otra transmisión, espera un momento y vuelve a pulsar Iniciar.",
"rpg_t_restrict_q": "Tras el inicio de sesión sin conexión, los juegos piden desactivar las restricciones de la consola.",
"rpg_t_restrict_a": "Usa Deshacer el inicio de sesión en esta página y reinicia, o quita la restricción en Ajustes › Familia y controles parentales › Restricciones de la consola PS5 (código 0000 salvo que lo hayas cambiado).",
