"mesh_rp_started": "{name} empezó a jugar en esta consola",
"rp_keys_body3": "Haz clic en la imagen para jugar con el teclado; Esc devuelve el puntero. Doble clic para pantalla completa; allí, Esc breve es Círculo y mantener Esc sale de pantalla completa. Teclas, sonido y más en Ajustes.",
"rp_play_description2": "Transmite una PS5 a esta app y juega con mando, teclado o pantalla táctil. Despierta sola una consola en modo de reposo y sigue jugando mientras usas otras pantallas.",
