"dump_decrypt_risk": "Descifrar puede congelar la consola",
"dump_decrypt_risk_body": "Para descifrar, el ayudante cambia brevemente, por cada ejecutable, una parte del sistema que usan todos los programas. Si el juego lee un archivo en ese momento, la consola puede congelarse y necesitar un apagado forzado. Quédate en la pantalla de inicio del juego mientras tanto. Solo firmware hasta 13.60; en firmware más reciente el volcado es una copia simple.",
