"notif_ps5_hint": "Mensajes que ps5upload ha mostrado en la pantalla de tu PS5 (un PIN de Remote Play, un truco activado), leídos de nuevo desde su ayudante cada 5 segundos. No es el panel de notificaciones de la PS5.",
